INSERT INTO convocatoria_content (torneoid, section_id, section_type, title, content, sort_order, enabled)
VALUES (354, 'descripcion', 'text', 'Descripción', '{"text":"Atlas Country Club celebra su 56° Torneo Anual de Golf, que se llevará a cabo del 20 al 25 de Julio de 2026.\\n\\nSe jugará a 54 hoyos stroke play, excepto las categorías 5a, 6a, Seniors y Damas, que se jugarán en formato Stableford al 80% del handicap. Sin corte, de acuerdo con las reglas de la U.S.G.A., F.M.G. y las reglas locales. Será responsabilidad de cada jugador leer las reglas, bases y términos de competencia antes de iniciar su salida.\\n\\nPremios destacados: O´yes en los hoyos par 3 (4, 7, 14 y 17) con bolsa de hasta $350,000 al primer lugar, autos y motocicletas para Hole In One en cada par 3, y un premio especial de $1.5 millones de pesos al primer Hole In One en el Hoyo 14 durante la última ronda de juego."}', 1, 1)
ON DUPLICATE KEY UPDATE
  section_type = VALUES(section_type),
  title = VALUES(title),
  content = VALUES(content),
  sort_order = VALUES(sort_order),
  enabled = VALUES(enabled);

INSERT INTO convocatoria_content (torneoid, section_id, section_type, title, content, sort_order, enabled)
VALUES (354, 'premiacion', 'premiacion', 'Premiación', '{"items":[{"categoria":"Trofeos por Categoría","premios":["Trofeos de colección, obra del escultor jalisciense Álvaro Cuevas, a los tres primeros lugares de cada categoría."]},{"categoria":"Premio Adicional — Mejor Score del Día","premios":["$7,750.00 (siete mil setecientos cincuenta pesos 00/100 M.N.) al mejor score del día por categoría. No repetible.","En categorías formato Stableford (Damas, D, E y Seniors) el ganador será la tarjeta con el mayor puntaje."]},{"categoria":"O´YES — Hoyos 4, 7, 14 y 17 (Premios por hoyo par 3)","premios":["1° Lugar: $350,000 pesos","2° Lugar: $155,000 pesos","3° Lugar: $75,000 pesos","4° Lugar: $37,500 pesos","5° Lugar: Inscripción Anual 2027","6° Lugar: Reloj Hamilton","7° Lugar: Apple iPad 10.2\\"","8° Lugar: Apple iPad 10.2\\"","9° Lugar: Bocina Bose","10° Lugar: Bocina Bose","En caso de empate en O´yes se calificará en orden cronológico, considerando mejor posicionado al que se haya marcado primero. El O´yes no podrá ser repetible por la misma persona en el mismo hoyo."]},{"categoria":"HOLE IN ONE — Hoyo 4","premios":["SUV Geely Monjaro GF 2026","Carrito de golf SEVEN 2026","Motocicleta Triumph Speed 400 2026"]},{"categoria":"HOLE IN ONE — Hoyo 7","premios":["SUV GAC Enkoo HEV 2025","Carrito de golf Club Car 2026","Motocicleta Indian Sixty Bobber"]},{"categoria":"HOLE IN ONE — Hoyo 14","premios":["Automóvil de lujo","Moto Triumph Scrambler 400 2026","Carrito de golf Hardy Carts","1.5 millones de pesos al primer Hole In One en el Hoyo 14 durante la última ronda del torneo (premio especial)."]},{"categoria":"HOLE IN ONE — Hoyo 17","premios":["BMW 220i Coupé 2027","Moto Triumph Scrambler 1200 X 2026","Carrito de golf Golf Lozano"]},{"categoria":"Notas Hole In One","premios":["En caso de un segundo Hole In One se considerará como mejor O´yes y así sucesivamente, siguiendo el orden cronológico del evento.","El deducible será pagado por el ganador.","El premio de 1.5 millones de pesos del Hoyo 14 aplica únicamente en la tercera ronda de juego de cada una de las categorías."]}]}', 5, 1)
ON DUPLICATE KEY UPDATE
  section_type = VALUES(section_type),
  title = VALUES(title),
  content = VALUES(content),
  sort_order = VALUES(sort_order),
  enabled = VALUES(enabled);

