INSERT INTO convocatoria_content (torneoid, section_id, section_type, title, content, sort_order, enabled)
VALUES (354, 'reglas', 'reglas', 'Reglas Locales', '{"items":[{"titulo":"Reglas Generales","contenido":"Se jugará a 54 hoyos stroke play, excepto las categorías 5a, 6a, Seniors y Damas que se jugarán en formato Stableford al 80% del handicap, sin corte, de acuerdo con las reglas de la U.S.G.A., F.M.G. y las reglas locales. Será responsabilidad de cada jugador leer las reglas, bases y términos de competencia antes de iniciar su salida."},{"titulo":"Handicap / INDEX","contenido":"Cada participante quedará registrado de acuerdo con su GHIN o carta constancia de su INDEX debidamente acreditado por su Club con la firma del Profesional, Gerente o Comisión de Golf. Cada jugador es responsable de entregar su hándicap; no se aceptarán jugadores sin este requisito. El INDEX vigente será válido al día 15 de Junio del 2026, determinando éste la categoría del jugador."},{"titulo":"Vestimenta","contenido":"Durante las rondas de juego los caballeros deberán utilizar ropa apropiada para la práctica del golf; no se permite el uso de shorts, bermudas ni jeans. Las damas deberán utilizar playera tipo polo, pantalón o falda propia de golf."},{"titulo":"Marcas de Salida","contenido":"Campeonato: marcas negras. 1ª: marcas azules. 2ª a 6ª: marcas blancas. Seniors: marcas doradas. Super Senior: marcas platino. Damas: marcas rojas."},{"titulo":"División de Categorías (2ª a 6ª)","contenido":"Las categorías 2ª, 3ª, 4ª, 5ª y 6ª (salidas de marcas blancas) serán determinadas dividiendo el número de jugadores inscritos de manera cronológica y de acuerdo a su INDEX. El límite de la división de las categorías se notificará en cuanto queden definidas."},{"titulo":"Carritos de Golf","contenido":"Se permitirá el uso de carritos de golf (propiedad del Club) en todas las categorías."},{"titulo":"Notas Generales","contenido":"La cuota de inscripción deberá estar liquidada en su totalidad, su registro en la plataforma concluido y su carta de hándicap INDEX entregada a más tardar el 7 de Julio de 2026 para ser acreedor a algún premio. El pago del torneo no garantiza su participación a menos que esté confirmado por el área de Inscripciones. Cualquier controversia será resuelta por la Comisión de Golf. La Comisión se reserva el derecho de hacer los cambios pertinentes para el mejor funcionamiento del torneo."}],"reglamento":[{"titulo":"Sistemas de Juego — Stroke Play","contenido":"CAMPEONATO, Premier y AA: 54 hoyos sin hándicap. Pasan el corte 12 jugadores (sin empates) después de 36 hoyos.\\n\\nCATEGORÍA A: 72 hoyos sin hándicap. Habrá 2 cortes: el primero a los 36 hoyos jugados pasando los mejores 24 jugadores sin empates y, el segundo corte, a 54 hoyos jugados pasando a la final los primeros 12 jugadores sin empates.\\n\\nCAMPEONATO MAYORES: 54 hoyos con hándicap al 80%. Pasan el corte los mejores 4 gross y los mejores 4 neto después de 36 hoyos. Los jugadores deberán tener 50 años o más cumplidos el primer día de juego.\\n\\nDAMAS A y B: 54 hoyos con el 80% de hándicap. Pasan el corte las mejores 4 gross y las mejores 4 neto después de 36 hoyos. En caso de que alguna jugadora pase a la final Gross y también a la final Neto, deberá jugar únicamente por el trofeo Gross; en este caso la quinta mejor jugadora en Neto, jugará por el trofeo Neto."},{"titulo":"Sistemas de Juego — Stableford (acumulado)","contenido":"DAMAS C, D y E: 54 hoyos con el 80% de hándicap. Habrá corte a los 36 hoyos jugados. Las mejores 8 jugadoras sin empates pasarán a la final conservando el acumulado de puntos.\\n\\nB, C y D: 72 hoyos con hándicap al 80%. Habrá 2 cortes: el primero a los 36 hoyos jugados pasando los mejores 24 jugadores sin empates y, el segundo corte, a 54 hoyos jugados pasando a la final los primeros 12 jugadores sin empates.\\n\\nSENIORS A y B: 54 hoyos con hándicap al 80%. Pasan el corte los mejores 12 jugadores de cada categoría después de 36 hoyos. Los jugadores deberán tener 60 o más años cumplidos al primer día de juego.\\n\\nDAMAS ESTELARES: 27 hoyos sin hándicap con corte a los 18 hoyos jugados pasando las mejores 6 jugadoras sin empates."},{"titulo":"Marcas de Salida","contenido":"CAMPEONATO: Negras.\\nPremier y AA: Azules.\\nA, B, C, D y CAMPEONATO MAYORES: Blancas.\\nDAMAS: Rojas.\\nDAMAS ESTELARES: Naranjas."},{"titulo":"Hora de Salida","contenido":"Tanto en stroke play como en stableford, los jugadores deberán estar en su mesa de salida, listos para jugar, a la hora estipulada independientemente del orden en que les toque salir. Si el jugador se presenta hasta con cinco minutos de retraso a su mesa de salida, tendrá 2 golpes de penalidad en el primer hoyo. Después de estos 5 minutos, será descalificado."},{"titulo":"Ronda Estipulada","contenido":"9 hoyos."},{"titulo":"Vestimenta","contenido":"Según el código interno del Reglamento de Golf."},{"titulo":"Transportación Automotriz","contenido":"Los jugadores podrán utilizar transportación automotriz para ellos mismos, su equipo y su caddie."},{"titulo":"Caddie","contenido":"Es obligatorio para todos los jugadores contratar los servicios de un caddie (siempre y cuando el club pueda proporcionarles uno), el cual puede ser compartido con otro jugador."},{"titulo":"Puntuación Stableford","contenido":"• 2 golpes más que el par (doble bogey): sin puntos\\n• 1 golpe más que el par (bogey): un punto\\n• Par: dos puntos\\n• 1 golpe menos que par (birdie): tres puntos\\n• 2 golpes menos que par (águila): cuatro puntos\\n• 3 golpes menos que par (albatros): cinco puntos"},{"titulo":"Suspensión de Juego","contenido":"• Suspensión inmediata del juego: una nota prolongada de sirena.\\n• Suspensión del juego: tres notas consecutivas de sirena.\\n• Reanudación del juego: dos notas consecutivas de sirena.\\n\\nCuando el juego ha sido suspendido por el Comité por una situación peligrosa (una nota prolongada de sirena), todos los jugadores deberán SUSPENDER DE INMEDIATO SU JUEGO. Si un jugador no interrumpe de inmediato su juego en esta circunstancia, será DESCALIFICADO."},{"titulo":"Entrega de Scores","contenido":"Es responsabilidad del jugador que su tarjeta sea entregada. Ésta deberá entregarse en un lapso no mayor a 15 minutos a partir del momento en el que el grupo haya terminado de jugar el último hoyo de la ronda. Las tarjetas se entregarán en la mesa de recepción ubicada junto a la caseta del starter. Si el jugador no entrega su tarjeta de score en el tiempo indicado será descalificado."},{"titulo":"Cómo Decidir Empates — Para el Corte","contenido":"Se tomará como primer criterio el mejor score de la última ronda. Si persistiera el empate, el segundo criterio será comparar el score de los hoyos del 10 al 18 de la última ronda, continuando con los hoyos del 13 al 18, 16 al 18 y por último el hoyo 18. En caso de persistir el empate se hará lo mismo con los hoyos del 1 al 9."},{"titulo":"Cómo Decidir Empates — Para Trofeos","contenido":"Sólo para el primer lugar en todas las categorías Gross o Neto se jugará a muerte súbita SIN VENTAJAS (en caso de no poder iniciar o continuar con un desempate a muerte súbita por oscuridad o mal clima, el desempate se llevará a cabo como lo señalado para desempatar para el corte). Para decidir el resto de los empates se utilizarán los mismos criterios que para el corte. Cualquier empate en el campo iniciará a la hora y por el hoyo establecidos por el Comité."},{"titulo":"Premios de O’yes por Día","contenido":"Importante: un jugador no podrá ganar más de un O’yes por día."},{"titulo":"Cierre de la Competencia","contenido":"Al iniciarse la ceremonia de premiación."},{"titulo":"Recomendaciones","contenido":"• Marcar la bola antes de levantarla para identificarla (penalidad: 1 golpe si no se marca).\\n• No hay \\"dadas\\", se debe embocar en todos los hoyos. En Stableford deberá embocarse toda bola que cuente para obtener puntos, de lo contrario podrá ser levantada sin embocar.\\n• No se debe cambiar bola en green (penalidad: un golpe).\\n• Máximo 14 bastones.\\n• No se puede dar ni pedir consejo.\\n• Presentarse en su hoyo de salida 5 minutos antes."},{"titulo":"Aviso General","contenido":"ESTAS REGLAS LOCALES Y TÉRMINOS DE LA COMPETENCIA DEJAN SIN EFECTO CUALQUIER REGLA LOCAL O TÉRMINO DE LA COMPETENCIA QUE EL CLUB UTILIZA PARA EL JUEGO NORMAL DE SUS SOCIOS, SE ENCUENTREN O NO PUBLICADAS EN CUALQUIER PARTE."}]}', 7, 1)
ON DUPLICATE KEY UPDATE
  section_type = VALUES(section_type),
  title = VALUES(title),
  content = VALUES(content),
  sort_order = VALUES(sort_order),
  enabled = VALUES(enabled);

INSERT INTO convocatoria_content (torneoid, section_id, section_type, title, content, sort_order, enabled)
VALUES (354, 'competencias', 'competencias', 'Competencias Especiales', '{"items":[{"nombre":"O´YES (Closest to the Pin)","descripcion":"Premios en los hoyos par 3 (4, 7, 14 y 17). En caso de empate se califica en orden cronológico (mejor posicionado el que se marcó primero). El O´yes no es repetible por la misma persona en el mismo hoyo.","premios":"1°: $350,000 · 2°: $155,000 · 3°: $75,000 · 4°: $37,500 · 5°: Inscripción Anual 2027 · 6°: Reloj Hamilton · 7°-8°: Apple iPad 10.2\\" · 9°-10°: Bocina Bose."},{"nombre":"Hole In One — Hoyo 4","descripcion":"Premio al primer Hole In One en el Hoyo 4. El deducible será pagado por el ganador.","premios":"SUV Geely Monjaro GF 2026 + Carrito SEVEN 2026 + Motocicleta Triumph Speed 400 2026."},{"nombre":"Hole In One — Hoyo 7","descripcion":"Premio al primer Hole In One en el Hoyo 7.","premios":"SUV GAC Enkoo HEV 2025 + Carrito Club Car 2026 + Motocicleta Indian Sixty Bobber."},{"nombre":"Hole In One — Hoyo 14","descripcion":"Premio al primer Hole In One en el Hoyo 14. El premio especial de 1.5 millones aplica únicamente en la tercera (última) ronda de juego de cada categoría.","premios":"Automóvil de lujo + Moto Triumph Scrambler 400 2026 + Carrito Hardy Carts + 1.5 millones de pesos (última ronda)."},{"nombre":"Hole In One — Hoyo 17","descripcion":"Premio al primer Hole In One en el Hoyo 17.","premios":"BMW 220i Coupé 2027 + Moto Triumph Scrambler 1200 X 2026 + Carrito Golf Lozano."},{"nombre":"Premio Adicional — Mejor Score del Día","descripcion":"Premio al mejor score del día por categoría. No repetible. En categorías Stableford (Damas, D, E y Seniors) gana la tarjeta con mayor puntaje.","premios":"$7,750.00 por día por categoría."},{"nombre":"¡Grandes Sorpresas!","descripcion":"Rifas durante la feria del pueblo y la ceremonia de premiación entre los participantes inscritos.","premios":"Diversos premios sorpresa."}]}', 8, 1)
ON DUPLICATE KEY UPDATE
  section_type = VALUES(section_type),
  title = VALUES(title),
  content = VALUES(content),
  sort_order = VALUES(sort_order),
  enabled = VALUES(enabled);

